public bool IsTrungAc
{
	get { return trungAcEnabled; }
	set
	{
		lock (trungAcLock)
		{
			if (trungAcEnabled == value) return;
			if (!value)
			{
				trungAcLoginOwner = trungAcOwner ?? (TLBB == null ? null : TLBB.Id);
				trungAcLoginSuppressed = true;
			}
			trungAcEnabled = value;
			ResetTrungAcSession();
		}
	}
}

